import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { Api } from '../../core/api';
import { BookingStore } from '../../core/booking';
import { Checkout } from './checkout';

describe('Checkout page', () => {
  it('shows messages only after a field is left and on invalid pay', async () => {
    sessionStorage.clear();
    TestBed.configureTestingModule({ providers: [provideRouter([]), { provide: Api, useValue: {} }] });
    const store = TestBed.inject(BookingStore);
    store.openFor(1);
    store.setItems([
      { row: 7, columnStart: 12, columnEnd: 12, couch: false, ids: ['R7C12'], price: 32 },
    ]);
    const fixture = TestBed.createComponent(Checkout);
    fixture.detectChanges();
    await fixture.whenStable();
    const el = fixture.nativeElement as HTMLElement;
    const q = (id: string) => el.querySelector<HTMLElement>(`[data-testid="${id}"]`);

    expect(q('pay-button')!.textContent!.trim()).toBe('Pay 32.00 PLN');
    expect(q('first-name-error')).toBeNull();
    const input = q('first-name-input') as HTMLInputElement;
    input.dispatchEvent(new Event('blur'));
    await fixture.whenStable();
    expect(q('first-name-error')!.textContent).toBe('First name is required');
    input.value = 'A';
    input.dispatchEvent(new Event('input'));
    await fixture.whenStable();
    expect(q('first-name-error')!.textContent).toBe('First name must be at least 2 characters');
    expect(store.booking()!.form.firstName).toBe('A');

    expect(q('email-error')).toBeNull();
    q('pay-button')!.click();
    await fixture.whenStable();
    expect(q('email-error')!.textContent).toBe('Email is required');
    expect(q('terms-error')!.textContent).toBe('You must accept the terms and conditions');
    expect(q('phone-error')).toBeNull();
  });
});

import { Component, DestroyRef, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { MatButton } from '@angular/material/button';
import { MatCheckbox } from '@angular/material/checkbox';
import { ErrorStateMatcher } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { Api } from '../../core/api';
import { BookingStore, emptyForm } from '../../core/booking';
import { CheckoutValues } from '../../core/models';
import { formatPrice, seatsFromItems } from '../../core/seats';
import { ToastService } from '../../core/toast';

type Field = keyof CheckoutValues;
type Messages = Record<Field, string | null>;

function validateEmail(value: string): boolean {
  if (!/^[^\s@]+@[^\s@]+$/.test(value)) return false;
  const domain = value.slice(value.indexOf('@') + 1);
  return /^.+\..+$/.test(domain);
}

export function validate(values: CheckoutValues): Messages {
  return {
    firstName: !values.firstName
      ? 'First name is required'
      : values.firstName.length < 2
        ? 'First name must be at least 2 characters'
        : null,
    lastName: !values.lastName
      ? 'Last name is required'
      : values.lastName.length < 2
        ? 'Last name must be at least 2 characters'
        : null,
    email: !values.email ? 'Email is required' : validateEmail(values.email) ? null : 'Enter a valid email address',
    confirmEmail: !values.confirmEmail
      ? 'Confirm email is required'
      : values.confirmEmail === values.email
        ? null
        : 'Email addresses do not match',
    phone: values.phone === '' || /^\d{9}$/.test(values.phone) ? null : 'Phone number must be exactly 9 digits',
    terms: values.terms ? null : 'You must accept the terms and conditions',
  };
}

@Component({
  selector: 'app-checkout',
  imports: [MatButton, MatCheckbox, MatFormFieldModule, MatInputModule, ReactiveFormsModule],
  templateUrl: './checkout.html',
  styleUrl: './checkout.scss',
})
export class Checkout {
  private readonly api = inject(Api);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly store = inject(BookingStore);
  private readonly toast = inject(ToastService);

  private readonly initial = this.store.booking()?.form ?? emptyForm();

  protected readonly form = new FormGroup({
    firstName: new FormControl(this.initial.firstName, { nonNullable: true }),
    lastName: new FormControl(this.initial.lastName, { nonNullable: true }),
    email: new FormControl(this.initial.email, { nonNullable: true }),
    confirmEmail: new FormControl(this.initial.confirmEmail, { nonNullable: true }),
    phone: new FormControl(this.initial.phone, { nonNullable: true }),
    terms: new FormControl(this.initial.terms, { nonNullable: true }),
  });

  private readonly tick = signal(0);
  protected readonly processing = signal(false);
  protected readonly payLabel = computed(() =>
    this.processing() ? 'Processing…' : `Pay ${formatPrice(this.store.total())}`,
  );

  protected readonly messages = computed<Messages>(() => {
    this.tick();
    const values = this.form.getRawValue();
    const all = validate(values);
    const result = { ...all };
    for (const field of Object.keys(all) as Field[]) {
      if (!this.form.controls[field].touched) result[field] = null;
    }
    return result;
  });

  protected readonly matchers: Record<Field, ErrorStateMatcher> = {
    firstName: this.matcher('firstName'),
    lastName: this.matcher('lastName'),
    email: this.matcher('email'),
    confirmEmail: this.matcher('confirmEmail'),
    phone: this.matcher('phone'),
    terms: this.matcher('terms'),
  };

  constructor() {
    this.form.events.pipe(takeUntilDestroyed(inject(DestroyRef))).subscribe(() => {
      this.tick.update((n) => n + 1);
    });
    this.form.valueChanges.pipe(takeUntilDestroyed(inject(DestroyRef))).subscribe(() => {
      this.store.setForm(this.form.getRawValue());
    });
  }

  private matcher(field: Field): ErrorStateMatcher {
    return { isErrorState: () => this.form.controls[field].touched && validate(this.form.getRawValue())[field] !== null };
  }

  protected touchTerms(): void {
    this.form.controls.terms.markAsTouched();
    this.tick.update((n) => n + 1);
  }

  protected back(): void {
    void this.router.navigate(['/screenings', this.route.snapshot.paramMap.get('id'), 'summary']);
  }

  protected pay(): void {
    if (this.processing()) return;
    const values = this.form.getRawValue();
    if (Object.values(validate(values)).some((message) => message !== null)) {
      this.form.markAllAsTouched();
      this.tick.update((n) => n + 1);
      this.toast.show('The form contains errors');
      return;
    }
    const booking = this.store.booking()!;
    this.processing.set(true);
    this.api
      .createReservation({
        screeningId: booking.screeningId,
        seats: seatsFromItems(this.store.items()),
        customer: {
          firstName: values.firstName,
          lastName: values.lastName,
          email: values.email,
          phone: values.phone,
        },
        totalPrice: this.store.total(),
      })
      .subscribe({
        next: () => {
          this.store.markPaid(values.email);
          this.processing.set(false);
          void this.router.navigateByUrl('/confirmation');
        },
        error: () => {
          this.processing.set(false);
          this.toast.show('Payment failed. Please try again.');
        },
      });
  }
}

import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { of, throwError } from 'rxjs';
import { Api } from '../../core/api';
import { MovieList } from './movie-list';

describe('MovieList', () => {
  afterEach(() => vi.useRealTimers());

  async function render(api: Partial<Api>) {
    vi.useFakeTimers({ toFake: ['Date'], now: new Date(2026, 8, 15, 10) });
    await TestBed.configureTestingModule({
      providers: [provideRouter([]), provideNativeDateAdapter(), { provide: Api, useValue: api }],
    }).compileComponents();
    const fixture = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    await fixture.whenStable();
    return fixture.nativeElement as HTMLElement;
  }

  const q = (el: HTMLElement, id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));

  it('shows day buttons and the movies of today ordered by time', async () => {
    const el = await render({
      movies: () =>
        of([
          { id: 1, title: 'A', genre: 'Drama', runtimeMinutes: 128, format: 'PL dubbing' as const },
          { id: 2, title: 'B', genre: 'Comedy', runtimeMinutes: 90, format: 'PL subtitles' as const },
        ]),
      screenings: () =>
        of([
          { id: 5, movieId: 1, date: '2026-09-15', time: '18:00', occupiedSeats: [] },
          { id: 4, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: [] },
          { id: 6, movieId: 2, date: '2026-09-16', time: '16:00', occupiedSeats: [] },
        ]),
    });
    expect(q(el, 'day-button').map((b) => b.textContent!.trim())).toEqual([
      'Today',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
    ]);
    expect(q(el, 'day-button')[0].dataset['selected']).toBe('true');
    expect(q(el, 'movie-card').length).toBe(1);
    expect(q(el, 'screening-button').map((b) => b.textContent!.trim())).toEqual(['16:00', '18:00']);
    expect(q(el, 'movie-runtime')[0].textContent).toBe('128 min');
  });

  it('shows the error state', async () => {
    const el = await render({ movies: () => throwError(() => new Error('x')), screenings: () => of([]) });
    expect(q(el, 'movies-error')[0].textContent).toContain('Failed to load movies');
    expect(q(el, 'movies-retry-button').length).toBe(1);
  });
});

import { Component, DestroyRef, computed, effect, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toSignal } from '@angular/core/rxjs-interop';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { MatButton } from '@angular/material/button';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { Subject, catchError, forkJoin, of, startWith, switchMap, tap } from 'rxjs';
import { Api } from '../../core/api';
import { addDays, parseIso, startOfToday, toIso, weekdayName } from '../../core/dates';
import { Movie, Screening } from '../../core/models';

interface Day {
  date: string;
  label: string;
}

interface MovieCard {
  movie: Movie;
  screenings: Screening[];
}

@Component({
  selector: 'app-movie-list',
  imports: [MatButton, MatDatepickerModule, MatFormFieldModule, MatInputModule, ReactiveFormsModule],
  templateUrl: './movie-list.html',
  styleUrl: './movie-list.scss',
})
export class MovieList {
  private readonly api = inject(Api);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly destroyRef = inject(DestroyRef);

  protected readonly today = startOfToday();
  protected readonly days: Day[] = Array.from({ length: 5 }, (_, i) => {
    const date = addDays(this.today, i);
    return { date: toIso(date), label: i === 0 ? 'Today' : weekdayName(date) };
  });

  private readonly query = toSignal(this.route.queryParamMap, { initialValue: this.route.snapshot.queryParamMap });

  protected readonly selectedDate = computed(() => {
    const parsed = parseIso(this.query().get('date'));
    return parsed && parsed >= this.today ? toIso(parsed) : toIso(this.today);
  });

  protected readonly pickerControl = new FormControl<Date | null>(null);

  protected readonly status = signal<'loading' | 'error' | 'loaded'>('loading');
  private readonly movies = signal<Movie[]>([]);
  private readonly screenings = signal<Screening[]>([]);
  private readonly reload$ = new Subject<void>();

  protected readonly cards = computed<MovieCard[]>(() => {
    const date = this.selectedDate();
    const byMovie = new Map<number, Screening[]>();
    for (const screening of this.screenings()) {
      if (screening.date !== date) continue;
      const list = byMovie.get(screening.movieId) ?? [];
      list.push(screening);
      byMovie.set(screening.movieId, list);
    }
    return this.movies()
      .filter((movie) => byMovie.has(movie.id))
      .map((movie) => ({
        movie,
        screenings: [...byMovie.get(movie.id)!].sort((a, b) => a.time.localeCompare(b.time)),
      }));
  });

  constructor() {
    this.reload$
      .pipe(
        startWith(undefined),
        tap(() => this.status.set('loading')),
        switchMap(() =>
          forkJoin([this.api.movies(), this.api.screenings()]).pipe(
            tap(([movies, screenings]) => {
              this.movies.set(movies);
              this.screenings.set(screenings);
              this.status.set('loaded');
            }),
            catchError(() => {
              this.status.set('error');
              return of(null);
            }),
          ),
        ),
        takeUntilDestroyed(this.destroyRef),
      )
      .subscribe();

    effect(() => {
      const selected = this.selectedDate();
      const inButtons = this.days.some((day) => day.date === selected);
      this.pickerControl.setValue(inButtons ? null : parseIso(selected), { emitEvent: false });
    });
  }

  protected retry(): void {
    this.reload$.next();
  }

  protected selectDate(date: string): void {
    void this.router.navigate([], { relativeTo: this.route, queryParams: { date } });
  }

  protected onPickerChange(value: Date | null): void {
    if (!value || isNaN(value.getTime())) {
      this.resetPicker();
      return;
    }
    const day = new Date(value.getFullYear(), value.getMonth(), value.getDate());
    if (day < this.today) {
      this.resetPicker();
      return;
    }
    this.selectDate(toIso(day));
  }

  private resetPicker(): void {
    const selected = this.selectedDate();
    const inButtons = this.days.some((day) => day.date === selected);
    this.pickerControl.setValue(inButtons ? null : parseIso(selected), { emitEvent: false });
  }

  protected openSeats(screeningId: number): void {
    void this.router.navigate(['/screenings', screeningId, 'seats']);
  }
}

import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { of } from 'rxjs';
import { Api } from '../../core/api';
import { BookingStore } from '../../core/booking';
import { SeatSelection } from './seat-selection';

describe('SeatSelection', () => {
  async function render(occupied: string[]) {
    sessionStorage.clear();
    await TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        {
          provide: Api,
          useValue: {
            screening: () => of({ id: 1, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: occupied }),
            movie: () => of({ id: 1, title: 'T', genre: 'G', runtimeMinutes: 1, format: 'PL dubbing' }),
          },
        },
      ],
    }).compileComponents();
    const fixture = TestBed.createComponent(SeatSelection);
    fixture.detectChanges();
    await fixture.whenStable();
    return fixture.nativeElement as HTMLElement;
  }

  const q = (el: HTMLElement, id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));

  it('renders the auditorium geometry', async () => {
    const el = await render(['R3C7', 'R15C5']);
    expect(q(el, 'seat-row').length).toBe(15);
    expect(q(el, 'seat').length + q(el, 'couch').length).toBe(308);
    expect(q(el, 'couch').length).toBe(12);
    expect(q(el, 'aisle').length).toBe(30);
    expect(q(el, 'row-label-left').length).toBe(15);
    expect(q(el, 'seat').filter((s) => s.dataset['state'] === 'accessible').length).toBe(6);
    expect(q(el, 'seat').find((s) => s.dataset['row'] === '3' && s.dataset['column'] === '7')!.dataset['state']).toBe(
      'unavailable',
    );
    expect(q(el, 'couch').find((c) => c.dataset['columnStart'] === '5')!.dataset['state']).toBe('unavailable');
    expect(q(el, 'seat').some((s) => s.dataset['row'] === '1' && s.dataset['column'] === '4')).toBe(false);
    expect(q(el, 'seat-map-subtitle')[0].textContent).toBe('Show Date: Tuesday 15 Sep 16:00');
  });

  it('selects, caps and summarises', async () => {
    const el = await render([]);
    const click = (row: string, column: string) =>
      q(el, 'seat')
        .find((s) => s.dataset['row'] === row && s.dataset['column'] === column)!
        .click();
    click('7', '12');
    click('7', '11');
    q(el, 'couch')[0].click();
    TestBed.tick();
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 4');
    expect(q(el, 'selected-seats-row').map((r) => r.textContent)).toEqual(['Row 7: 11, 12', 'Row 15: 1-2']);
    expect(TestBed.inject(BookingStore).total()).toBe(32 * 2 + 89);
    q(el, 'couch')[0].click();
    TestBed.tick();
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 2');
  });
});

import { Component, DestroyRef, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MatButton } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { map, switchMap } from 'rxjs';
import { Api } from '../../core/api';
import { BookingStore } from '../../core/booking';
import { formatShowDate } from '../../core/dates';
import { Movie, Screening } from '../../core/models';
import {
  COUCH_ROW,
  MAX_SEATS,
  ROWS,
  SeatState,
  TicketItem,
  isAccessible,
  itemLabel,
  itemsFromSeats,
  seatId,
} from '../../core/seats';
import { ToastService } from '../../core/toast';

interface Cell {
  key: string;
  couch: boolean;
  columnStart: number;
  columnEnd: number;
  gridColumn: number;
  span: number;
  ids: string[];
}

interface RowLayout {
  row: number;
  cells: Cell[];
}

// grid: 1 label, 2-5 seats 1-4, 6 aisle, 7-22 seats 5-20, 23 aisle, 24-27 seats 21-24, 28 label
function gridColumn(column: number): number {
  if (column <= 4) return column + 1;
  if (column <= 20) return column + 2;
  return column + 3;
}

function buildLayout(): RowLayout[] {
  const rows: RowLayout[] = [];
  for (let row = 1; row <= ROWS; row++) {
    const cells: Cell[] = [];
    if (row === COUCH_ROW) {
      for (let start = 1; start <= 24; start += 2) {
        cells.push({
          key: `${row}-${start}`,
          couch: true,
          columnStart: start,
          columnEnd: start + 1,
          gridColumn: gridColumn(start),
          span: 2,
          ids: [seatId(row, start), seatId(row, start + 1)],
        });
      }
    } else {
      for (let column = row <= 10 ? 5 : 1; column <= 24; column++) {
        cells.push({
          key: `${row}-${column}`,
          couch: false,
          columnStart: column,
          columnEnd: column,
          gridColumn: gridColumn(column),
          span: 1,
          ids: [seatId(row, column)],
        });
      }
    }
    rows.push({ row, cells });
  }
  return rows;
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButton],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(Api);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly store = inject(BookingStore);
  private readonly toast = inject(ToastService);

  protected readonly layout = buildLayout();
  protected readonly legend: { state: SeatState; label: string }[] = [
    { state: 'available', label: 'Available' },
    { state: 'selected', label: 'Selected' },
    { state: 'unavailable', label: 'Unavailable' },
    { state: 'accessible', label: 'Accessible' },
  ];

  protected readonly screening = signal<Screening | null>(null);
  protected readonly movie = signal<Movie | null>(null);
  protected readonly loaded = computed(() => this.screening() !== null && this.store.booking() !== null);

  protected readonly subtitle = computed(() => {
    const screening = this.screening();
    return screening ? `Show Date: ${formatShowDate(screening.date, screening.time)}` : '';
  });

  private readonly occupied = computed(() => new Set(this.screening()?.occupiedSeats ?? []));
  private readonly selected = computed(() => new Set(this.store.booking()?.seats ?? []));
  protected readonly selectedCount = computed(() => this.selected().size);

  protected readonly selectedRows = computed(() => {
    const byRow = new Map<number, TicketItem[]>();
    for (const item of this.store.items()) {
      const list = byRow.get(item.row) ?? [];
      list.push(item);
      byRow.set(item.row, list);
    }
    return [...byRow.entries()]
      .sort((a, b) => a[0] - b[0])
      .map(([row, items]) => ({ row, text: `Row ${row}: ${items.map(itemLabel).join(', ')}` }));
  });

  constructor() {
    this.route.paramMap
      .pipe(
        map((params) => params.get('id') ?? ''),
        switchMap((id) =>
          this.api.screening(id).pipe(
            switchMap((screening) =>
              this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
            ),
          ),
        ),
        takeUntilDestroyed(inject(DestroyRef)),
      )
      .subscribe({
        next: ({ screening, movie }) => {
          this.store.openFor(screening.id);
          this.screening.set(screening);
          this.movie.set(movie);
        },
        error: () => void this.router.navigateByUrl('/', { replaceUrl: true }),
      });
  }

  protected state(row: number, cell: Cell): SeatState {
    if (cell.ids.some((id) => this.occupied().has(id))) return 'unavailable';
    if (cell.ids.every((id) => this.selected().has(id))) return 'selected';
    if (!cell.couch && isAccessible(row, cell.columnStart)) return 'accessible';
    return 'available';
  }

  protected toggle(row: number, cell: Cell): void {
    const state = this.state(row, cell);
    if (state === 'unavailable') return;
    const items = this.store.items();
    if (state === 'selected') {
      this.store.setItems(items.filter((item) => !item.ids.every((id) => cell.ids.includes(id))));
      return;
    }
    if (this.selectedCount() + cell.ids.length > MAX_SEATS) {
      this.toast.show('Maximum 10 seats per booking');
      return;
    }
    this.store.setItems(itemsFromSeats([...this.store.booking()!.seats, ...cell.ids]));
  }

  protected cancel(): void {
    this.store.clear();
    void this.router.navigateByUrl('/');
  }

  protected next(): void {
    if (this.selectedCount() === 0) return;
    void this.router.navigate(['/screenings', this.screening()!.id, 'summary']);
  }
}
